// 仅供个人使用：这些常量会原样进入订阅 JSON。
const ORIGIN = "https://dav.example.net";
const ROOT_PATH = "/dav/music/"; // 必须以 / 开头并以 / 结尾
const AUTHORIZATION = "Basic REPLACE_WITH_YOUR_BASE64_CREDENTIALS";
const ADAPTER_ID = "personal_webdav";
const PAGE_SIZE = 50;
const AUDIO_EXT = /\.(mp3|m4a|aac|flac|wav|ogg)$/i;

function xmlText(value) {
  return value.replace(/&#(x[0-9a-f]+|[0-9]+);|&(amp|lt|gt|quot|apos);/gi,
    (_, number, named) => {
      if (number) {
        const code = number[0].toLowerCase() === "x"
          ? parseInt(number.slice(1), 16) : parseInt(number, 10);
        return Number.isFinite(code) && code <= 0x10ffff
          ? String.fromCodePoint(code) : "";
      }
      return {amp: "&", lt: "<", gt: ">", quot: '"', apos: "'"}[named.toLowerCase()];
    });
}

function directAudioPath(href) {
  // DAV:href 通常是绝对路径，也可能是同一源站的完整 URL。
  let path = xmlText(href.trim());
  if (path.startsWith(ORIGIN + "/")) path = path.slice(ORIGIN.length);
  if (!path.startsWith(ROOT_PATH) || path.includes("?") || path.includes("#")) return null;
  const tail = path.slice(ROOT_PATH.length);
  if (!tail || tail.includes("/") || path.length > 256) return null;
  let filename;
  try { filename = decodeURIComponent(tail); } catch (_) { return null; }
  return AUDIO_EXT.test(filename) ? {path, filename} : null;
}

function parseListing(xml) {
  // 这里只读取 DAV:response 中的 href 和 collection 标记；不依赖 XML 前缀名称。
  const blocks = xml.match(/<(?:[\w.-]+:)?response\b[^>]*>[\s\S]*?<\/(?:[\w.-]+:)?response\s*>/gi) || [];
  const result = [];
  const seen = new Set();
  for (const block of blocks) {
    if (/<(?:[\w.-]+:)?collection\b/i.test(block)) continue;
    const href = block.match(/<(?:[\w.-]+:)?href\b[^>]*>([\s\S]*?)<\/(?:[\w.-]+:)?href\s*>/i);
    if (!href) continue;
    const file = directAudioPath(href[1]);
    if (file && !seen.has(file.path)) {
      seen.add(file.path);
      result.push(file);
    }
  }
  return result.sort((a, b) => a.filename.localeCompare(b.filename));
}

async function listAudioFiles() {
  const response = await voohHttp({
    url: ORIGIN + ROOT_PATH,
    method: "PROPFIND",
    headers: {
      Authorization: AUTHORIZATION,
      Depth: "1",
      "Content-Type": "application/xml; charset=utf-8"
    },
    body: '<?xml version="1.0" encoding="utf-8"?><d:propfind xmlns:d="DAV:"><d:prop><d:resourcetype/></d:prop></d:propfind>'
  });
  if (response.status === 401 || response.status === 403) {
    const error = new Error("个人 WebDAV 目录鉴权失败");
    error.code = "authentication";
    throw error;
  }
  if (response.status !== 207) {
    throw new Error("个人 WebDAV 目录读取失败，HTTP " + response.status);
  }
  return parseListing(response.text);
}

function toCandidate(file) {
  const title = file.filename.replace(AUDIO_EXT, "");
  return {
    source: {adapterId: ADAPTER_ID, sourceId: file.path},
    track: {id: "", title, artists: [], album: ""}
  };
}

function page(files, offset) {
  const items = files.slice(offset, offset + PAGE_SIZE).map(toCandidate);
  const next = offset + PAGE_SIZE;
  return {items, ...(next < files.length ? {nextCursor: String(next)} : {})};
}

globalThis.voohPlugin = {
  async search({text, cursor}) {
    const files = await listAudioFiles();
    const query = String(text || "").trim().toLocaleLowerCase();
    const matches = files.filter(file => file.filename.toLocaleLowerCase().includes(query));
    const offset = /^(0|[1-9][0-9]*)$/.test(String(cursor ?? "0")) ? Number(cursor ?? 0) : 0;
    return page(matches, offset);
  },

  async sections() {
    return [{id: "music", title: "我的 WebDAV 音乐"}];
  },

  async collection({id}) {
    if (id !== "music") return {items: []};
    // 当前发现页调用 collection 时不传分页 cursor，故仅展示前 50 首。
    return page(await listAudioFiles(), 0);
  },

  async resolve({source, candidate}) {
    if (source?.adapterId !== ADAPTER_ID || typeof source.sourceId !== "string") {
      throw new Error("歌曲来源无效");
    }
    const file = directAudioPath(source.sourceId);
    if (!file || file.path !== source.sourceId) throw new Error("文件路径无效");
    const selected = candidate && candidate.source?.adapterId === ADAPTER_ID &&
      candidate.source?.sourceId === source.sourceId ? candidate : toCandidate(file);
    return {
      candidate: selected,
      url: ORIGIN + file.path,
      protocol: "http",
      headers: {Authorization: AUTHORIZATION}
    };
  }
};复制

